.mc { font-family: "MC", system-ui; letter-spacing: .5px; }

/* sidebar */
.sidebar { background: #0d0e10; border-right: 1px solid var(--line); padding: 16px 12px; display: flex; flex-direction: column; gap: 18px; position: sticky; top: 0; height: 100vh; }
.brand { display: flex; align-items: center; gap: 10px; font-size: 20px; padding: 4px 6px; }
.brand-block { width: 26px; height: 26px; background: linear-gradient(var(--grass) 0 35%, #7a5230 35%); box-shadow: inset -3px -3px 0 rgba(0,0,0,.25); image-rendering: pixelated; }
nav { display: flex; flex-direction: column; gap: 2px; }
nav a { text-decoration: none; padding: 9px 10px; border-radius: 6px; color: var(--muted); display: flex; gap: 10px; align-items: center; }
nav a:hover { background: var(--panel); color: var(--text); }
nav a.active { background: var(--panel-2); color: var(--text); box-shadow: inset 3px 0 0 var(--grass); }
.ico { width: 18px; text-align: center; color: var(--grass); }
.side-stats { font-size: 12px; color: var(--muted); display: grid; gap: 4px; padding: 0 8px; }
.side-stats b { color: var(--text); font-variant-numeric: tabular-nums; }
.health { margin-top: auto; font-size: 11px; color: var(--faint); padding: 0 8px; display: grid; gap: 3px; }
.dot { display: inline-block; width: 7px; height: 7px; border-radius: 50%; margin-right: 6px; background: var(--faint); }
.dot.ok { background: var(--grass); } .dot.bad { background: var(--redstone); }

/* main */
main { padding: 22px 28px 60px; min-width: 0; }
h1 { font-family: "MC", system-ui; font-weight: normal; font-size: 26px; margin: 0 0 4px; }
h2 { font-size: 15px; margin: 22px 0 10px; color: var(--muted); font-weight: 600; text-transform: uppercase; letter-spacing: .08em; }
.sub { color: var(--muted); margin: 0 0 18px; }
.row { display: flex; gap: 10px; align-items: center; flex-wrap: wrap; }
.spacer { flex: 1; }
.card { background: var(--panel); border: 1px solid var(--line); border-radius: var(--radius); padding: 14px; }
.muted { color: var(--muted); } .faint { color: var(--faint); }
.mono { font-family: var(--mono); font-size: 12px; }

/* controls */
.btn { background: var(--panel-2); border: 1px solid var(--line); border-radius: 6px; padding: 7px 12px; cursor: pointer; white-space: nowrap; }
.btn:hover { border-color: #444a51; background: #2a2e33; }
.btn.primary { background: var(--grass-d); border-color: var(--grass); color: #fff; }
.btn.primary:hover { background: var(--grass); }
.btn.gold { background: #6b5410; border-color: var(--gold); }
.btn.danger { border-color: #7a2a2a; color: #ffb3b3; }
.btn.small { padding: 3px 8px; font-size: 12px; }
.btn:disabled { opacity: .45; cursor: default; }
input[type=text], input[type=number], input[type=search], select, textarea {
  background: #0f1012; border: 1px solid var(--line); border-radius: 6px; padding: 7px 10px; outline: none;
}
input:focus, select:focus, textarea:focus { border-color: var(--grass); }
textarea { width: 100%; resize: vertical; font-family: var(--mono); font-size: 12px; line-height: 1.5; }
label.field { display: grid; gap: 4px; font-size: 12px; color: var(--muted); }
label.field > input, label.field > select { color: var(--text); font-size: 14px; }

.chip { display: inline-flex; align-items: center; gap: 4px; padding: 3px 9px; border-radius: 99px; background: var(--panel-2); border: 1px solid var(--line); font-size: 12px; cursor: pointer; user-select: none; color: var(--muted); }
.chip:hover { color: var(--text); }
.chip.on { background: rgba(95,191,58,.18); border-color: var(--grass); color: #d8f5cc; }
.badge { display: inline-block; padding: 1px 7px; border-radius: 4px; font-size: 11px; background: var(--panel-2); color: var(--muted); border: 1px solid var(--line); }
.r-clean { color: #9fe58a; border-color: #2f5a22; }
.r-mild { color: var(--gold); border-color: #5f4d12; }
.r-explicit { color: #ff9a6b; border-color: #6a3216; }
.r-banned { color: #fff; background: #8a1f1f; border-color: #b33; }
.k-risk-high { color: #ff8f8f; border-color: #6a2020; }
.k-risk-medium { color: #e0c070; }

/* library */
.filters { display: grid; gap: 10px; margin-bottom: 14px; }
.chips { display: flex; flex-wrap: wrap; gap: 6px; }
.grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(210px, 1fr)); gap: 12px; }
.asset { background: var(--panel); border: 1px solid var(--line); border-radius: var(--radius); overflow: hidden; cursor: pointer; display: flex; flex-direction: column; transition: border-color .12s, transform .12s; }
.asset:hover { border-color: #4a5158; transform: translateY(-1px); }
.asset.sel { border-color: var(--grass); }
.thumb { aspect-ratio: 16/9; background: #0b0c0d center/cover no-repeat; position: relative; display: grid; place-items: center; }
.thumb.audio { background: linear-gradient(135deg, #1d2a1a, #13161a); }
.thumb .wave { font-size: 34px; color: var(--grass); opacity: .8; }
.thumb .dur { position: absolute; right: 6px; bottom: 6px; background: rgba(0,0,0,.75); padding: 1px 6px; border-radius: 4px; font-size: 11px; font-variant-numeric: tabular-nums; }
.thumb .play { position: absolute; left: 6px; bottom: 6px; width: 30px; height: 30px; border-radius: 50%; background: rgba(0,0,0,.7); border: 1px solid #555; display: grid; place-items: center; font-size: 12px; }
.thumb .play:hover { background: var(--grass-d); }
.asset .meta { padding: 8px 10px 10px; display: grid; gap: 5px; }
.asset .title { font-weight: 600; font-size: 13px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.asset .desc { font-size: 12px; color: var(--muted); display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; min-height: 2.9em; }
.asset .badges { display: flex; gap: 4px; flex-wrap: wrap; }
