.modal-head { padding: 14px 16px; border-bottom: 1px solid var(--line); display: flex; gap: 10px; align-items: center; }
.modal-body { padding: 8px; overflow-y: auto; }
.fs-entry { display: flex; gap: 10px; padding: 7px 10px; border-radius: 6px; cursor: pointer; align-items: center; }
