.proj-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(300px, 1fr)); gap: 14px; }
.proj { text-decoration: none; display: grid; gap: 10px; }
.proj:hover { border-color: #4a5158; }
.steps { display: flex; gap: 4px; }
.step { flex: 1; height: 6px; border-radius: 3px; background: var(--line); }
.step.done { background: var(--grass); }
.step-labels { display: flex; gap: 4px; font-size: 11px; color: var(--faint); }
.step-labels span { flex: 1; }

