.tabs { display: flex; gap: 2px; border-bottom: 1px solid var(--line); margin: 16px 0; }
.tab { padding: 9px 14px; cursor: pointer; color: var(--muted); border-bottom: 2px solid transparent; }
.tab.on { color: var(--text); border-bottom-color: var(--grass); }
