.two { display: grid; grid-template-columns: minmax(0, 1.4fr) minmax(0, 1fr); gap: 16px; }
@media (max-width: 1100px) { .two { grid-template-columns: 1fr; } }
video.main { width: 100%; border-radius: 8px; background: #000; aspect-ratio: 16/9; }

/* timeline */
