.tl-ruler { height: 20px; position: relative; border-bottom: 1px solid var(--line); margin-left: 84px; font-size: 10px; color: var(--faint); }
.tl-ruler span { position: absolute; top: 2px; transform: translateX(-50%); }
.tl-track { display: flex; align-items: center; height: 30px; border-bottom: 1px solid #24272b; }
.tl-name { width: 84px; flex: none; font-size: 11px; color: var(--muted); text-transform: uppercase; letter-spacing: .05em; position: sticky; left: 0; background: var(--panel); z-index: 2; height: 100%; display: flex; align-items: center; }
.tl-lane { position: relative; flex: 1; height: 100%; }
.tl-item { position: absolute; top: 4px; height: 22px; border-radius: 4px; font-size: 11px; padding: 3px 6px; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; cursor: pointer; border: 1px solid rgba(255,255,255,.12); min-width: 4px; }
.tl-item:hover { filter: brightness(1.25); z-index: 3; }
.ti-source { background: #2c4a22; } .ti-cutaway { background: #6b3a8a; } .ti-card { background: #2b5a7a; }
.ti-overlays { background: #2a6f6a; } .ti-text { background: #7a6420; } .ti-sfx { background: #7a2e2e; }
.ti-music { background: #2e3f7a; } .ti-bleeps { background: #a03030; } .ti-zooms { background: #5a5a5a; }
.tl-head { position: absolute; top: 0; bottom: 0; width: 2px; background: var(--gold); pointer-events: none; z-index: 5; box-shadow: 0 0 6px var(--gold); }
.legend { display: flex; gap: 14px; font-size: 12px; color: var(--muted); margin-top: 8px; flex-wrap: wrap; }

.transcript { max-height: 520px; overflow-y: auto; line-height: 2; }
.transcript .w { padding: 2px 3px; border-radius: 3px; cursor: pointer; }
.transcript .w:hover { background: var(--panel-2); }
.transcript .w.lowp { color: var(--gold); text-decoration: underline dotted; }
.transcript .ts { color: var(--faint); font-family: var(--mono); font-size: 11px; margin-right: 6px; }
.sheets { display: grid; grid-template-columns: repeat(auto-fill, minmax(320px, 1fr)); gap: 10px; }
.sheets img { width: 100%; border-radius: 6px; cursor: zoom-in; border: 1px solid var(--line); }
.evlist { max-height: 420px; overflow-y: auto; font-size: 13px; }
.evlist div { padding: 3px 6px; border-radius: 4px; cursor: pointer; display: flex; gap: 10px; }
.evlist div:hover { background: var(--panel-2); }
.empty { padding: 40px; text-align: center; color: var(--muted); border: 1px dashed var(--line); border-radius: var(--radius); }
.warn { color: var(--gold); font-size: 13px; }
.err { color: var(--redstone); }

