@font-face { font-family: "MC"; src: url("/media/pack/Fonts/Minecraft Regular.otf"); font-display: swap; }
@font-face { font-family: "MCTen"; src: url("/media/pack/Fonts/Minecraft Ten.ttf"); font-display: swap; }

:root {
  --bg: #121315;
  --panel: #1b1d20;
  --panel-2: #23262a;
  --line: #2f3338;
  --text: #e8eaed;
  --muted: #9aa0a6;
  --faint: #6b7178;
  --grass: #5fbf3a;
  --grass-d: #3f8f24;
  --gold: #ffcc33;
  --diamond: #4fe0d6;
  --redstone: #ff4b4b;
  --purple: #b072ff;
  --radius: 8px;
  --shadow: 0 8px 30px rgba(0,0,0,.45);
  --mono: ui-monospace, "Cascadia Code", Consolas, monospace;
}
* { box-sizing: border-box; }
html, body { height: 100%; }
body {
  margin: 0; background: var(--bg); color: var(--text);
  font: 14px/1.45 system-ui, "Segoe UI", Roboto, sans-serif;
  display: grid; grid-template-columns: 220px 1fr;
}
a { color: inherit; }
button, input, select, textarea { font: inherit; color: inherit; }
