.brand { display: flex; align-items: center; gap: 10px; font-size: 20px; padding: 4px 6px; }
.brand-block { width: 26px; height: 26px; background: linear-gradient(var(--grass) 0 35%, #7a5230 35%); box-shadow: inset -3px -3px 0 rgba(0,0,0,.25); image-rendering: pixelated; }
nav { display: flex; flex-direction: column; gap: 2px; }
