nav a:hover { background: var(--panel); color: var(--text); }
nav a.active { background: var(--panel-2); color: var(--text); box-shadow: inset 3px 0 0 var(--grass); }
.ico { width: 18px; text-align: center; color: var(--grass); }
.side-stats { font-size: 12px; color: var(--muted); display: grid; gap: 4px; padding: 0 8px; }
.side-stats b { color: var(--text); font-variant-numeric: tabular-nums; }
.health { margin-top: auto; font-size: 11px; color: var(--faint); padding: 0 8px; display: grid; gap: 3px; }
.dot { display: inline-block; width: 7px; height: 7px; border-radius: 50%; margin-right: 6px; background: var(--faint); }
.dot.ok { background: var(--grass); } .dot.bad { background: var(--redstone); }

