// MC Studio — single-page UI. No build step; talks to mcstudio/server.py.
const $ = (s, el = document) => el.querySelector(s);
const $$ = (s, el = document) => [...el.querySelectorAll(s)];
const view = $("#view");
const player = $("#player");
const esc = (s) => String(s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
const fmt = (t) => { if (t == null || isNaN(t)) return "–"; const m = Math.floor(t / 60), s = (t % 60).toFixed(1).padStart(4, "0"); return `${m}:${s}`; };
const fmtSize = (b) => b > 1e9 ? (b / 1e9).toFixed(1) + " GB" : b > 1e6 ? (b / 1e6).toFixed(1) + " MB" : (b / 1e3).toFixed(0) + " KB";
const packUrl = (p) => "/media/pack/" + p.split("/").map(encodeURIComponent).join("/");

async function api(path, opts = {}) {
  const r = await fetch(path, { headers: { "Content-Type": "application/json" }, ...opts,
    body: opts.body && typeof opts.body !== "string" ? JSON.stringify(opts.body) : opts.body });
  if (!r.ok) { let m = r.statusText; try { m = (await r.json()).detail || m; } catch {} throw new Error(m); }
  return r.json();
}
function toast(msg, err = false) {
  const t = $("#toast"); t.textContent = msg; t.className = "toast" + (err ? " err" : ""); t.hidden = false;
  clearTimeout(toast._t); toast._t = setTimeout(() => (t.hidden = true), 3500);
}
const store = { get: (k, d) => { try { return JSON.parse(localStorage.getItem(k)) ?? d; } catch { return d; } },
                set: (k, v) => { try { localStorage.setItem(k, JSON.stringify(v)); } catch {} } };

let TAX = null;
let pollers = [];
function clearPollers() { pollers.forEach(clearInterval); pollers = []; }

// ---------------------------------------------------------------- shell
async function boot() {
  TAX = await api("/api/taxonomy");
  refreshSide();
  window.addEventListener("hashchange", route);
  route();
}
async function refreshSide() {
  try {
    const [s, h] = await Promise.all([api("/api/stats"), api("/api/health")]);
    $("#sideStats").innerHTML = `<div><b>${s.tagged}</b> tagged assets</div>
      <div><b>${s.by_rating.banned || 0}</b> banned · <b>${s.by_risk.high || 0}</b> high-©</div>`;
    $("#health").innerHTML = ["ffmpeg", "assets_db", "claude"].map((k) =>
      `<div><span class="dot ${h[k] ? "ok" : k === "claude" ? "" : "bad"}"></span>${k === "claude" ? "claude CLI" : k}</div>`).join("");
  } catch {}
}
function route() {
  clearPollers();
  closeDrawer();
  const [, page, arg] = location.hash.split("/");
  $$("nav a").forEach((a) => a.classList.toggle("active", a.dataset.nav === (page === "project" ? "projects" : page || "projects")));
  ({ library: Library, new: NewEpisode, jobs: Jobs, project: () => Project(decodeURIComponent(arg || "")) }[page] || Projects)();
}

// ---------------------------------------------------------------- library
const LIB = store.get("lib", { q: "", category: [], moment: [], rating: ["clean", "mild"], ranked: false, offset: 0 });
async function Library() {
  view.innerHTML = `
    <div class="row"><div><h1>Asset library</h1><p class="sub">Every sound, meme, green screen and graphic in the Editing Pack, tagged for the auto-editor.</p></div></div>
    <div class="filters card">
      <div class="row">
        <input id="q" type="search" placeholder="Search: creeper, sad violin, bruh, diamond…" style="flex:1;min-width:240px" value="${esc(LIB.q)}">
        <select id="momentSel"><option value="">+ moment…</option>${Object.entries(TAX.moments).map(([k, v]) => `<option value="${k}" title="${esc(v)}">${k}</option>`).join("")}</select>
        <label class="chip ${LIB.ranked ? "on" : ""}" id="ranked" title="Use the planner's scoring (needs a moment or search)">★ Planner ranking</label>
      </div>
      <div class="chips" id="cats">${Object.keys(TAX.categories).filter((c) => c !== "reference").map((c) =>
        `<span class="chip ${LIB.category.includes(c) ? "on" : ""}" data-c="${c}" title="${esc(TAX.categories[c])}">${c.replace("_", " ")}</span>`).join("")}</div>
      <div class="row">
        <div class="chips" id="moments">${LIB.moment.map((m) => `<span class="chip on" data-m="${m}">${m} ✕</span>`).join("")}</div>
        <span class="spacer"></span>
        <div class="chips" id="ratings">${Object.keys(TAX.content_rating).map((r) =>
          `<span class="chip ${LIB.rating.includes(r) ? "on" : ""}" data-r="${r}">${r}</span>`).join("")}</div>
      </div>
    </div>
    <div class="row muted" id="count"></div>
    <div class="grid" id="grid"></div>
    <div class="pager" id="pager"></div>`;
  let t;
  $("#q").addEventListener("input", (e) => { clearTimeout(t); t = setTimeout(() => { LIB.q = e.target.value; LIB.offset = 0; load(); }, 250); });
  $("#momentSel").addEventListener("change", (e) => { if (e.target.value && !LIB.moment.includes(e.target.value)) LIB.moment.push(e.target.value); e.target.value = ""; LIB.offset = 0; Library(); });
  $("#moments").addEventListener("click", (e) => { const m = e.target.dataset.m; if (m) { LIB.moment = LIB.moment.filter((x) => x !== m); LIB.offset = 0; Library(); } });
  $("#cats").addEventListener("click", (e) => { const c = e.target.dataset.c; if (!c) return; toggle(LIB.category, c); e.target.classList.toggle("on"); LIB.offset = 0; load(); });
  $("#ratings").addEventListener("click", (e) => { const r = e.target.dataset.r; if (!r) return; toggle(LIB.rating, r); e.target.classList.toggle("on"); LIB.offset = 0; load(); });
  $("#ranked").addEventListener("click", (e) => { LIB.ranked = !LIB.ranked; e.target.classList.toggle("on"); load(); });
  load();

  async function load() {
    store.set("lib", LIB);
    const p = new URLSearchParams({ q: LIB.q, limit: 60, offset: LIB.offset, ranked: LIB.ranked });
    LIB.category.forEach((c) => p.append("category", c));
    LIB.moment.forEach((m) => p.append("moment", m));
    LIB.rating.forEach((r) => p.append("rating", r));
    const res = await api("/api/assets?" + p);
    let items = res.items;
    if (LIB.ranked) items = items.filter((a) => !LIB.rating.length || LIB.rating.includes(a.content_rating));
    $("#count").textContent = `${LIB.ranked ? items.length + " best matches" : res.total + " assets"}`;
    $("#grid").innerHTML = items.map(assetCard).join("") || `<div class="empty">No assets match. Loosen the filters.</div>`;
    $$("#grid .asset").forEach((el, i) => {
      el.addEventListener("click", (e) => { if (e.target.closest(".play")) return; openAsset(items[i].id); $$(".asset.sel").forEach((x) => x.classList.remove("sel")); el.classList.add("sel"); });
      const pb = $(".play", el); if (pb) pb.addEventListener("click", () => playAsset(items[i], pb));
    });
    const pages = Math.ceil(res.total / 60), cur = LIB.offset / 60;
    $("#pager").innerHTML = LIB.ranked || pages <= 1 ? "" :
      `<button class="btn small" ${cur === 0 ? "disabled" : ""} id="prev">← Prev</button><span>Page ${cur + 1} / ${pages}</span><button class="btn small" ${cur + 1 >= pages ? "disabled" : ""} id="next">Next →</button>`;
    $("#prev")?.addEventListener("click", () => { LIB.offset -= 60; load(); scrollTo(0, 0); });
    $("#next")?.addEventListener("click", () => { LIB.offset += 60; load(); scrollTo(0, 0); });
  }
}
function toggle(arr, v) { const i = arr.indexOf(v); i >= 0 ? arr.splice(i, 1) : arr.push(v); }
function ratingBadge(r) { return r ? `<span class="badge r-${r}">${r}</span>` : ""; }
function assetCard(a) {
  const audio = a.kind === "audio";
  const thumb = a.thumb ? `style="background-image:url('/media/catalog/${a.thumb}')"` : "";
  const playable = a.kind === "audio" || (a.kind === "video" && a.has_audio);
  return `<div class="asset" title="${esc(a.id)}">
    <div class="thumb ${audio ? "audio" : ""}" ${thumb}>
      ${audio ? `<span class="wave">${a.category === "music" ? "♫" : "♪"}</span>` : ""}
      ${playable ? `<span class="play" title="Play">▶</span>` : ""}
      ${a.duration_s ? `<span class="dur">${a.duration_s.toFixed(1)}s</span>` : ""}
    </div>
    <div class="meta">
      <div class="title">${esc(a.title)}</div>
      <div class="desc">${esc(a.description || "")}</div>
      <div class="badges"><span class="badge">${a.category}</span>${ratingBadge(a.content_rating)}
        ${a.copyright_risk === "high" ? `<span class="badge k-risk-high">© high</span>` : ""}
        ${a.key_mode && a.key_mode !== "none" ? `<span class="badge">${a.key_mode}</span>` : ""}
        ${a.score != null ? `<span class="badge" style="color:var(--gold)">★ ${a.score}</span>` : ""}</div>
    </div></div>`;
}
function playAsset(a, btn) {
  const url = packUrl(a.path);
  if (!player.paused && player.dataset.id === a.id) { player.pause(); btn.textContent = "▶"; return; }
  $$(".play").forEach((b) => (b.textContent = "▶"));
  player.src = url; player.dataset.id = a.id;
  player.currentTime = 0; player.play().catch(() => toast("Can't play this format in the browser", true));
  btn.textContent = "❚❚";
  player.onended = () => (btn.textContent = "▶");
}
function closeDrawer() { const d = $("#drawer"); d.hidden = true; d.innerHTML = ""; }
async function openAsset(id) {
  const a = await api("/api/assets/" + encodeURIComponent(id));
  const d = $("#drawer");
  const url = packUrl(a.path);
  const media = a.kind === "video" ? `<video src="${url}" controls preload="metadata"></video>`
    : a.kind === "audio" ? `<audio src="${url}" controls style="width:100%"></audio>`
    : a.kind === "image" ? `<img class="preview" src="${url}">`
    : a.thumb ? `<img class="preview" src="/media/catalog/${a.thumb}">` : "";
  const opt = (list, cur) => list.map((v) => `<option ${v === cur ? "selected" : ""}>${v}</option>`).join("");
  d.innerHTML = `<button class="btn small close" id="dclose">✕</button>
    <h3>${esc(a.title)}</h3>
    <div class="row" style="margin-bottom:10px"><code class="mono">${esc(a.id)}</code><button class="btn small" id="copyId">Copy ID</button></div>
    ${media}
    <p>${esc(a.description || "")}</p>
    <div class="chips">${a.moments.map((m) => `<span class="chip on">${m}</span>`).join("")}${a.roles.map((r) => `<span class="chip">${r}</span>`).join("")}</div>
    <dl class="kv">
      <dt>Category</dt><dd>${a.category} · ${esc(a.subfolder)}</dd>
      <dt>Rating</dt><dd>${ratingBadge(a.content_rating)} <span class="badge k-risk-${a.copyright_risk}">© ${a.copyright_risk || "?"}</span></dd>
      ${a.quote ? `<dt>Quote</dt><dd>“${esc(a.quote)}”</dd>` : ""}
      <dt>Energy / mood</dt><dd>${a.energy ?? "–"} / ${esc(a.mood || "–")}</dd>
      <dt>Duration</dt><dd>${a.duration_s ? a.duration_s.toFixed(2) + "s" : "–"} ${a.peak_s != null ? `· hit @ ${a.peak_s}s` : ""} ${a.use_in != null ? `· use ${a.use_in}–${a.use_out}s` : ""}</dd>
      ${a.width ? `<dt>Size</dt><dd>${a.width}×${a.height}${a.fps ? " @ " + a.fps : ""}</dd>` : ""}
      ${a.key_mode && a.key_mode !== "none" ? `<dt>Key</dt><dd>${a.key_mode} ${a.key_color || ""}</dd>` : ""}
      <dt>Placement</dt><dd>${a.placement || "–"} · ${a.frequency || "–"}</dd>
      <dt>Tags</dt><dd>${a.tags.map(esc).join(", ")}</dd>
      ${a.notes ? `<dt>Notes</dt><dd>${esc(a.notes)}</dd>` : ""}
      <dt>Used in</dt><dd>${a.used_in.map((u) => `${esc(u.project)} (${u.n})`).join(", ") || "never"}</dd>
      <dt>File</dt><dd class="mono">${esc(a.path)}</dd>
    </dl>
    <h2>Correct tags</h2>
    <div style="display:grid;gap:8px">
      <div class="row">
        <label class="field">Rating<select id="eRating">${opt(Object.keys(TAX.content_rating), a.content_rating)}</select></label>
        <label class="field">Copyright<select id="eRisk">${opt(Object.keys(TAX.copyright_risk), a.copyright_risk)}</select></label>
        <label class="field">Energy<input id="eEnergy" type="number" min="1" max="5" value="${a.energy ?? 3}" style="width:70px"></label>
      </div>
      <label class="field">Moments (comma separated)<input id="eMoments" type="text" value="${esc(a.moments.join(", "))}"></label>
      <label class="field">Description<input id="eDesc" type="text" value="${esc(a.description || "")}"></label>
      <label class="field">Notes<input id="eNotes" type="text" value="${esc(a.notes || "")}"></label>
      <div><button class="btn primary" id="eSave">Save correction</button> <span class="faint" style="font-size:12px">stored in catalog/overrides.json</span></div>
    </div>`;
  d.hidden = false;
  $("#dclose").onclick = closeDrawer;
  $("#copyId").onclick = () => { navigator.clipboard.writeText(a.id); toast("Copied " + a.id); };
  $("#eSave").onclick = async () => {
    const moments = $("#eMoments").value.split(",").map((s) => s.trim()).filter(Boolean);
    const bad = moments.filter((m) => !TAX.moments[m]);
    if (bad.length) return toast("Unknown moments: " + bad.join(", "), true);
    try {
      await api("/api/assets/" + encodeURIComponent(a.id), { method: "PATCH", body: { fields: {
        content_rating: $("#eRating").value, copyright_risk: $("#eRisk").value, energy: +$("#eEnergy").value,
        moments, description: $("#eDesc").value, notes: $("#eNotes").value || null } } });
      toast("Saved"); openAsset(a.id); refreshSide();
    } catch (e) { toast(e.message, true); }
  };
}

// ---------------------------------------------------------------- projects
async function Projects() {
  const ps = await api("/api/projects");
  view.innerHTML = `<div class="row"><div><h1>Episodes</h1><p class="sub">Each episode runs through the assembly line: transcribe → analyze → scaffold → plan → render.</p></div>
    <span class="spacer"></span><a class="btn primary" href="#/new">＋ New episode</a></div>
    ${ps.length ? `<div class="proj-grid">${ps.map(projCard).join("")}</div>` : `<div class="empty">No episodes yet. <a href="#/new">Create one from an OBS recording.</a></div>`}`;
}
function projCard(p) {
  const steps = [p.transcribed, p.analyzed, p.has_edit, p.segments > 1, p.outputs.length > 0];
  return `<a class="card proj" href="#/project/${encodeURIComponent(p.slug)}">
    <div class="row"><b style="font-size:16px">${esc(p.title)}</b><span class="spacer"></span>${p.job ? `<span class="badge" style="color:var(--gold)">⚙ ${p.job.stage}</span>` : ""}</div>
    <div class="muted mono">${esc(p.slug)} · ${fmt(p.duration_s)} raw · ${p.segments} segments</div>
    <div class="steps">${steps.map((s) => `<div class="step ${s ? "done" : ""}"></div>`).join("")}</div>
    <div class="step-labels"><span>transcript</span><span>signals</span><span>scaffold</span><span>edited</span><span>rendered</span></div>
    <div class="faint" style="font-size:12px">updated ${p.modified.replace("T", " ")}</div></a>`;
}

// ---------------------------------------------------------------- new episode
async function NewEpisode() {
  view.innerHTML = `<h1>New episode</h1><p class="sub">Point at your OBS recording. Best setup: OBS → Settings → Output → Recording → tick audio tracks 1 (game) and 2 (mic), so the mic is perfectly in sync.</p>
    <div class="card" style="display:grid;gap:12px;max-width:760px">
      <div class="row">
        <label class="field" style="flex:1">Episode slug<input id="slug" type="text" placeholder="ep01-creeper-chaos"></label>
        <label class="field" style="flex:1.4">Title<input id="title" type="text" placeholder="I Survived 100 Days With Creepers Only"></label>
      </div>
      <label class="field">Gameplay recording<div class="row"><input id="game" type="text" style="flex:1" placeholder="C:\\Users\\…\\Videos\\2026-10-06 20-11-02.mkv"><button class="btn" data-pick="game">Browse…</button></div></label>
      <label class="field">Separate mic recording (optional — leave empty if the mic is audio track 2 of the recording)<div class="row"><input id="mic" type="text" style="flex:1"><button class="btn" data-pick="mic">Browse…</button></div></label>
      <div class="row">
        <label class="field">Mic offset (s)<input id="off" type="number" step="0.01" value="0" style="width:110px"></label>
        <label class="field">Mic audio track<input id="mstream" type="number" min="0" placeholder="auto" style="width:110px"></label>
        <span class="spacer"></span>
        <label class="chip on" id="auto">⚡ Run auto pipeline after creating</label>
      </div>
      <div class="row"><button class="btn primary" id="create">Create episode</button><span class="muted" id="cmsg"></span></div>
    </div>`;
  $$("[data-pick]").forEach((b) => (b.onclick = (e) => { e.preventDefault(); pickFile((p) => {
    $("#" + b.dataset.pick).value = p;
    if (b.dataset.pick === "game" && !$("#slug").value) $("#slug").value = "ep-" + p.split(/[\\/]/).pop().replace(/\.[^.]+$/, "").toLowerCase().replace(/[^a-z0-9]+/g, "-").slice(0, 30);
  }); }));
  $("#auto").onclick = (e) => e.target.classList.toggle("on");
  $("#create").onclick = async () => {
    const body = { slug: $("#slug").value.trim(), title: $("#title").value.trim() || null, game: $("#game").value.trim(),
      mic: $("#mic").value.trim() || null, mic_offset: +$("#off").value || 0, mic_stream: $("#mstream").value === "" ? null : +$("#mstream").value };
    if (!body.slug || !body.game) return toast("Slug and gameplay recording are required", true);
    try {
      $("#create").disabled = true; $("#cmsg").textContent = "Probing recording…";
      await api("/api/projects", { method: "POST", body });
      if ($("#auto").classList.contains("on")) store.set("autorun:" + body.slug, ["transcribe", "analyze", "scaffold"]);
      location.hash = "#/project/" + encodeURIComponent(body.slug);
    } catch (e) { toast(e.message, true); $("#create").disabled = false; $("#cmsg").textContent = ""; }
  };
}
async function pickFile(cb, start = store.get("fsdir", "")) {
  const m = $("#modal");
  async function show(path) {
    const r = await api("/api/fs?path=" + encodeURIComponent(path));
    store.set("fsdir", r.path);
    m.innerHTML = `<div class="modal-box"><div class="modal-head"><b>Choose a recording</b><code class="mono faint" style="flex:1;overflow:hidden;text-overflow:ellipsis">${esc(r.path)}</code><button class="btn small" id="mclose">✕</button></div>
      <div class="modal-body">${r.parent ? `<div class="fs-entry" data-dir="${esc(r.parent)}">⬆ <span class="n">..</span></div>` : ""}
      ${r.entries.map((e) => `<div class="fs-entry" ${e.dir ? `data-dir="${esc(e.path)}"` : `data-file="${esc(e.path)}"`}>${e.dir ? "📁" : "🎬"} <span class="n">${esc(e.name)}</span><span class="faint mono">${e.dir ? "" : fmtSize(e.size) + " · " + e.mtime.replace("T", " ")}</span></div>`).join("") || `<div class="empty">No media here</div>`}</div></div>`;
    m.hidden = false;
    $("#mclose").onclick = () => (m.hidden = true);
    $$(".fs-entry", m).forEach((el) => (el.onclick = () => el.dataset.dir ? show(el.dataset.dir) : (m.hidden = true, cb(el.dataset.file))));
  }
  show(start);
}

// ---------------------------------------------------------------- project page
const STAGE_INFO = [
  ["transcribe", "Transcribe", "Word-level captions from the mic (Whisper large-v3-turbo, CPU).", (p) => p.transcribed],
  ["analyze", "Analyze", "Find yells, game booms, scene cuts, dead air; frame sheets.", (p) => p.analyzed],
  ["scaffold", "Scaffold", "First cut: dead air removed, music bed, captions on.", (p) => p.has_edit],
  ["plan", "Plan with Claude", "Beats, memes, SFX, zooms, text: the creative pass.", (p) => p.segments > 1 && p.edit && (p.edit.audio?.sfx?.length || 0) > 0],
  ["check", "Check", "Validate EDL, pacing densities, rating & copyright.", () => false],
  ["preview", "Preview render", "Fast 540p30 render to review.", (p) => p.outputs.some((o) => o.name.includes("preview"))],
  ["render", "Final render", "1080p60, −14 LUFS, ready to upload.", (p) => p.outputs.some((o) => !o.name.includes("preview"))],
];
async function Project(slug) {
  let p;
  try { p = await api("/api/projects/" + encodeURIComponent(slug)); } catch (e) { view.innerHTML = `<div class="empty">${esc(e.message)}</div>`; return; }
  const tab = store.get("tab:" + slug, "pipeline");
  view.innerHTML = `<div class="row"><div><h1>${esc(p.title)}</h1><div class="muted mono">${esc(slug)} · ${fmt(p.duration_s)} raw recording${p.project.notes?.length ? ` · <span class="warn">${esc(p.project.notes.join("; "))}</span>` : ""}</div></div></div>
    <div class="tabs">${[["pipeline", "Pipeline"], ["timeline", "Timeline & player"], ["transcript", "Transcript"], ["signals", "Signals & frames"], ["edl", "Edit JSON"]].map(([k, l]) =>
      `<div class="tab ${k === tab ? "on" : ""}" data-tab="${k}">${l}</div>`).join("")}</div>
    <div id="tabBody"></div>`;
  $$(".tab").forEach((t) => (t.onclick = () => { store.set("tab:" + slug, t.dataset.tab); Project(slug); }));
  ({ pipeline: PipelineTab, timeline: TimelineTab, transcript: TranscriptTab, signals: SignalsTab, edl: EdlTab }[tab] || PipelineTab)(p, $("#tabBody"));
}

async function PipelineTab(p, el) {
  const claude = await api("/api/claude?slug=" + encodeURIComponent(p.slug));
  el.innerHTML = `<div class="pipeline">${STAGE_INFO.map(([k, name, desc, done], i) => `
      <div class="stage ${done(p) ? "done" : ""}"><div class="n"><span class="num">${done(p) ? "✓" : i + 1}</span>${name}</div><p>${desc}</p>
      <div class="row">${k === "plan" ? `<button class="btn gold small" data-plan>${claude.available ? "Run Claude" : "Get prompt"}</button>`
        : `<button class="btn small ${i === 0 && !p.transcribed ? "primary" : ""}" data-run="${k}">Run</button>`}
      ${k === "transcribe" ? `<button class="btn small" data-run="transcribe-fast" title="small.en model, much faster">Fast</button>` : ""}
      ${k === "scaffold" && p.has_edit ? `<button class="btn small danger" data-run="scaffold-force" title="Overwrite edit.json (backed up)">Redo</button>` : ""}</div></div>`).join("")}</div>
    <div class="row" style="margin-top:14px"><button class="btn primary" id="runAll">⚡ Run everything to preview</button><span class="muted" style="font-size:12px">transcribe → analyze → scaffold → check → preview (skips finished steps)</span><span class="spacer"></span><button class="btn small danger" id="cancel" hidden>Cancel job</button></div>
    <h2>Job log</h2><div class="console" id="log">No job running.</div>
    ${p.outputs.length ? `<h2>Renders</h2><div class="two"><video class="main" controls src="/media/project/${encodeURIComponent(p.slug)}/out/${encodeURIComponent(p.outputs[0].name)}?v=${Date.now()}"></video>
      <div class="card">${p.outputs.map((o) => `<div class="row" style="padding:4px 0"><a href="/media/project/${encodeURIComponent(p.slug)}/out/${encodeURIComponent(o.name)}" target="_blank">${esc(o.name)}</a><span class="spacer"></span><span class="faint">${fmtSize(o.size)} · ${o.mtime.replace("T", " ")}</span></div>`).join("")}
      ${p.report?.warnings?.length ? `<h2>Render warnings</h2>${p.report.warnings.map((w) => `<div class="warn">⚠ ${esc(w)}</div>`).join("")}` : ""}</div></div>` : ""}`;

  let current = p.job?.id || null;
  const queue = store.get("autorun:" + p.slug, []);
  store.set("autorun:" + p.slug, []);
  async function start(stage, body) {
    try { const j = await api(`/api/projects/${encodeURIComponent(p.slug)}/run/${stage}`, { method: "POST", body: body || {} }); current = j.id; poll(); }
    catch (e) { toast(e.message, true); queue.length = 0; }
  }
  async function poll() {
    if (!current) return;
    const j = await api("/api/jobs/" + current);
    const log = $("#log"); if (!log) return;
    const atBottom = log.scrollTop + log.clientHeight >= log.scrollHeight - 30;
    log.textContent = `$ ${j.stage} (${j.status}, ${j.elapsed}s)\n` + j.log.join("\n");
    if (atBottom) log.scrollTop = log.scrollHeight;
    $("#cancel").hidden = j.status !== "running";
    if (j.status !== "running") {
      current = null;
      if (j.status === "done" && queue.length) return start(queue.shift());
      toast(`${j.stage}: ${j.status}`, j.status !== "done");
      setTimeout(() => Project(p.slug), 600);
    }
  }
  pollers.push(setInterval(poll, 1000));
  $$("[data-run]", el).forEach((b) => (b.onclick = () => start(b.dataset.run)));
  $("#cancel").onclick = () => current && api(`/api/jobs/${current}/cancel`, { method: "POST" });
  $("#runAll").onclick = () => {
    const steps = [!p.transcribed && "transcribe", !p.analyzed && "analyze", !p.has_edit && "scaffold", "check", "preview"].filter(Boolean);
    queue.push(...steps.slice(1)); start(steps[0]);
  };
  $("[data-plan]", el).onclick = () => {
    const m = $("#modal");
    m.innerHTML = `<div class="modal-box"><div class="modal-head"><b>Creative pass with Claude</b><span class="spacer"></span><button class="btn small" id="mclose">✕</button></div>
      <div class="modal-body" style="padding:16px;display:grid;gap:10px">
        <p class="muted" style="margin:0">${claude.available ? "This runs Claude Code headless with the mc-edit skill. It can edit files in this project and run mcs commands." : "The claude CLI isn't on PATH. Paste this prompt into Claude Code (desktop app, Code tab, opened on the Minecraft Channel folder)."}</p>
        <textarea id="prompt" rows="7">${esc(claude.prompt)}</textarea>
        <label class="field">Extra direction (optional)<input id="extra" type="text" placeholder="e.g. lean on Minecraft sounds, keep it family friendly, cold open with the creeper"></label>
        <div class="row"><button class="btn" id="copyP">Copy prompt</button>${claude.available ? `<button class="btn gold" id="goP">Run Claude</button>` : ""}</div></div></div>`;
    m.hidden = false;
    const full = () => $("#prompt").value + ($("#extra").value ? " Direction from the creator: " + $("#extra").value : "");
    $("#mclose").onclick = () => (m.hidden = true);
    $("#copyP").onclick = () => { navigator.clipboard.writeText(full()); toast("Prompt copied"); };
    if ($("#goP")) $("#goP").onclick = () => { m.hidden = true; start("plan", { prompt: full() }); };
  };
  if (current) poll(); else if (queue.length) start(queue.shift());
}

async function TimelineTab(p, el) {
  const tl = await api(`/api/projects/${encodeURIComponent(p.slug)}/timeline`);
  const out = p.outputs[0];
  const pxs = store.get("zoom", 40);
  el.innerHTML = `<div class="two"><div>${out ? `<video class="main" id="vid" controls src="/media/project/${encodeURIComponent(p.slug)}/out/${encodeURIComponent(out.name)}?v=${encodeURIComponent(out.mtime)}"></video>
      <div class="faint" style="font-size:12px;margin-top:4px">${esc(out.name)}: ${tl.duration ? "click the timeline to seek" : ""}</div>` : `<div class="empty">No render yet. Run a preview from the Pipeline tab.</div>`}</div>
    <div class="card" id="itemInfo"><b>Timeline</b><p class="muted">${fmt(tl.duration)} edited from ${fmt(p.duration_s)} raw (${p.duration_s ? Math.round(100 * tl.duration / p.duration_s) : 0}% kept). Click any block for details.</p>
      ${tl.warnings.map((w) => `<div class="warn">⚠ ${esc(w)}</div>`).join("")}</div></div>
    <div class="row" style="margin:14px 0 6px"><h2 style="margin:0">Tracks</h2><span class="spacer"></span><span class="muted" style="font-size:12px">zoom</span><input type="range" id="tlz" min="8" max="160" value="${pxs}"></div>
    <div class="tl" id="tl"></div>
    <div class="legend"><span>■ <span style="color:#6fbf4f">source</span></span><span style="color:#b07fd8">■ cutaway</span><span style="color:#4fb3ab">■ overlay</span><span style="color:#d4b040">■ text</span><span style="color:#d46060">■ sfx</span><span style="color:#6f86d8">■ music</span></div>`;
  const draw = (pps) => {
    const W = Math.max(tl.duration * pps, 300);
    const step = pps > 60 ? 1 : pps > 20 ? 5 : pps > 8 ? 10 : 30;
    let ruler = "";
    for (let t = 0; t <= tl.duration; t += step) ruler += `<span style="left:${t * pps}px">${fmt(t).replace(/\.\d$/, "")}</span>`;
    const order = [["segments", "Video"], ["zooms", "Zoom/shake"], ["overlays", "Overlays"], ["text", "Text"], ["sfx", "SFX"], ["music", "Music"], ["bleeps", "Bleeps"]];
    $("#tl").innerHTML = `<div class="tl-inner" style="width:${W + 84}px"><div class="tl-ruler" style="width:${W}px">${ruler}</div>
      ${order.filter(([k]) => tl.tracks[k]?.length || k === "segments").map(([k, name]) => `<div class="tl-track"><div class="tl-name">${name}</div><div class="tl-lane">
        ${(tl.tracks[k] || []).map((it, i) => {
          const cls = k === "segments" ? "ti-" + it.type : "ti-" + k;
          return `<div class="tl-item ${cls}" data-k="${k}" data-i="${i}" style="left:${it.start * pps}px;width:${Math.max(3, (it.end - it.start) * pps - 1)}px" title="${esc(it.label)} ${fmt(it.start)}–${fmt(it.end)}">${esc(it.label)}</div>`; }).join("")}
      </div></div>`).join("")}<div class="tl-head" id="head" style="left:84px"></div></div>`;
    $$(".tl-item").forEach((b) => (b.onclick = (e) => { e.stopPropagation(); const it = tl.tracks[b.dataset.k][b.dataset.i]; info(b.dataset.k, it); seek(it.start); }));
    $("#tl .tl-inner").onclick = (e) => { const r = $("#tl .tl-inner").getBoundingClientRect(); seek(Math.max(0, (e.clientX - r.left - 84) / pps)); };
    el._pps = pps;
  };
  const seek = (t) => { const v = $("#vid"); if (v) { v.currentTime = t; } moveHead(t); };
  const moveHead = (t) => { const h = $("#head"); if (h) h.style.left = 84 + t * el._pps + "px"; };
  const info = (k, it) => {
    $("#itemInfo").innerHTML = `<b>${esc(it.label)}</b><div class="muted">${k} · ${fmt(it.start)} → ${fmt(it.end)} (${(it.end - it.start).toFixed(2)}s)</div>
      ${it.src_in != null ? `<div class="mono" style="margin-top:6px">source ${fmt(it.src_in)} → ${fmt(it.src_out)}${it.speed !== 1 ? ` @ ${it.speed}×` : ""} ${it.effects?.length ? "· " + it.effects.join(", ") : ""}</div>` : ""}
      ${it.thumb ? `<img src="/media/catalog/${it.thumb}" style="width:100%;margin-top:8px;border-radius:6px">` : ""}
      ${it.asset ? `<div class="row" style="margin-top:8px"><code class="mono">${esc(it.asset)}</code><button class="btn small" id="openA">Open asset</button></div>` : ""}`;
    $("#openA")?.addEventListener("click", () => openAsset(it.asset));
  };
  draw(pxs);
  $("#tlz").oninput = (e) => { store.set("zoom", +e.target.value); draw(+e.target.value); };
  $("#vid")?.addEventListener("timeupdate", (e) => moveHead(e.target.currentTime));
}

function TranscriptTab(p, el) {
  if (!p.transcript) { el.innerHTML = `<div class="empty">No transcript yet. Run Transcribe on the Pipeline tab.</div>`; return; }
  el.innerHTML = `<div class="two"><div class="card transcript" id="tr">${p.transcript.segments.map((s) =>
      `<div><span class="ts">${fmt(s.start)}</span>${s.words.map((w) => `<span class="w ${w.p < 0.5 ? "lowp" : ""}" data-t="${w.start}" title="${fmt(w.start)} · p=${w.p}">${esc(w.word)}</span>`).join(" ")}</div>`).join("")}</div>
    <div><video class="main" id="src" controls preload="metadata" src="${p.game_url ? encodeURI(p.game_url) : ""}"></video>
      <p class="muted" style="font-size:12px">Raw recording (source time). Click a word to jump there. Dotted words are low-confidence: fix misheard Minecraft words in <code>work/transcript.json</code>.</p>
      <div class="card"><b>${p.transcript.segments.length}</b> segments · model <code>${esc(p.transcript.model)}</code> · ${p.transcript.segments.reduce((n, s) => n + s.words.length, 0)} words</div></div></div>`;
  $("#tr").onclick = (e) => { const t = e.target.dataset.t; if (t != null) { const v = $("#src"); v.currentTime = +t; v.play(); } };
}

function SignalsTab(p, el) {
  const s = p.signals;
  const evs = s ? [...(s.voice_peaks || []), ...(s.game_peaks || []), ...(s.scene_cuts || [])].sort((a, b) => a.t - b.t) : [];
  el.innerHTML = !s ? `<div class="empty">No signals yet. Run Analyze on the Pipeline tab.</div>` : `
    <div class="two"><div><video class="main" id="src" controls preload="metadata" src="${p.game_url ? encodeURI(p.game_url) : ""}"></video></div>
    <div class="card"><b>${evs.length} events</b> <span class="muted">· ${(s.silences || []).length} silences &gt; 1.5s</span>
      <div class="evlist" id="evs">${evs.map((e) => `<div data-t="${e.t}"><span class="mono">${fmt(e.t)}</span><span style="color:${e.type === "voice_peak" ? "var(--gold)" : e.type === "game_peak" ? "var(--redstone)" : "var(--diamond)"}">${e.type}</span><span class="faint">${e.above_baseline_db ? "+" + e.above_baseline_db + " dB" : ""}</span></div>`).join("")}</div></div></div>
    ${p.beats ? `<h2>Beat sheet</h2><pre class="card mono" style="white-space:pre-wrap">${esc(p.beats)}</pre>` : ""}
    <h2>Frame sheets</h2><div class="sheets">${p.sheets.map((f) => `<a href="/media/project/${encodeURIComponent(p.slug)}/${f}" target="_blank"><img loading="lazy" src="/media/project/${encodeURIComponent(p.slug)}/${f}"></a>`).join("")}</div>`;
  $("#evs")?.addEventListener("click", (e) => { const d = e.target.closest("[data-t]"); if (d) { const v = $("#src"); v.currentTime = Math.max(0, +d.dataset.t - 2); v.play(); } });
}

function EdlTab(p, el) {
  el.innerHTML = !p.edit ? `<div class="empty">No edit.json yet. Run Scaffold first.</div>` : `
    <div class="row" style="margin-bottom:8px"><span class="muted">Hand-edit the EDL. Each save keeps a copy in <code>history/</code>. Spec: <code>.claude/skills/mc-edit/references/edl.md</code></span><span class="spacer"></span>
      <button class="btn" id="fmtJ">Format</button><button class="btn primary" id="saveJ">Save</button></div>
    <textarea id="ej" rows="34" spellcheck="false">${esc(JSON.stringify(p.edit, null, 2))}</textarea>
    <div id="jerr" class="err"></div>`;
  if (!p.edit) return;
  const parse = () => { try { $("#jerr").textContent = ""; return JSON.parse($("#ej").value); } catch (e) { $("#jerr").textContent = e.message; return null; } };
  $("#fmtJ").onclick = () => { const j = parse(); if (j) $("#ej").value = JSON.stringify(j, null, 2); };
  $("#saveJ").onclick = async () => { const j = parse(); if (!j) return;
    try { await api(`/api/projects/${encodeURIComponent(p.slug)}/edit`, { method: "PUT", body: { edit: j } }); toast("Saved edit.json"); }
    catch (e) { $("#jerr").textContent = e.message; } };
}

// ---------------------------------------------------------------- jobs
async function Jobs() {
  const js = await api("/api/jobs");
  view.innerHTML = `<h1>Jobs</h1><p class="sub">Pipeline runs since the studio server started.</p>
    ${js.length ? `<div class="card">${js.slice().reverse().map((j) => `<div class="row" style="padding:6px 0;border-bottom:1px solid var(--line)">
      <a href="#/project/${encodeURIComponent(j.slug)}">${esc(j.slug)}</a><b>${esc(j.stage)}</b><span class="badge ${j.status === "done" ? "r-clean" : j.status === "running" ? "r-mild" : "r-explicit"}">${j.status}</span>
      <span class="spacer"></span><span class="faint mono">${j.elapsed}s</span></div>`).join("")}</div>` : `<div class="empty">No jobs yet.</div>`}`;
  pollers.push(setInterval(() => location.hash === "#/jobs" && Jobs(), 3000));
}

boot();

