# /// script
# requires-python = ">=3.11"
# dependencies = ["numpy>=2.1", "pillow>=11"]
# ///
"""Find exact AND near duplicates across asset folders.

    uv run studio/catalog/dedupe.py "Editing Pack" "Asset Pack v2/_extracted" --out studio/catalog/dedupe.json

Exact:  full-content SHA-1.
Near:   audio  - duration within 2 % and loudness-envelope correlation >= 0.96 (same sound, other encode)
        video  - duration within 2 % and 3 frame dHashes within 6 bits (same clip, other export)
        image  - dHash within 4 bits and same aspect (same picture, other size/format)
Keeper per group: already in the first folder given (keeps existing catalog ids) > higher quality
(resolution, bitrate, lossless) > cleaner file name.
"""
from __future__ import annotations

import argparse
import hashlib
import json
import re
import subprocess
from concurrent.futures import ThreadPoolExecutor
from pathlib import Path

import numpy as np
from PIL import Image

ROOT = Path(__file__).resolve().parents[2]
AUDIO = {".mp3", ".wav", ".m4a", ".flac", ".ogg", ".aac"}
VIDEO = {".mp4", ".mov", ".webm", ".wmv", ".avi", ".mkv"}
IMAGE = {".png", ".jpg", ".jpeg", ".webp", ".gif"}
JUNK = re.compile(r"\(\s*\d+\s*kbps\s*\)|\(HD\)|\[Mpgun\.com\]|y2mate\.com|yt1s\.com|\(\d+k\)|\(\d\)|copy|copie", re.I)


def sha1(p: Path) -> str:
    h = hashlib.sha1()
    with p.open("rb") as f:
        while b := f.read(1 << 20):
            h.update(b)
    return h.hexdigest()


def probe(p: Path) -> dict:
    r = subprocess.run(["ffprobe", "-v", "error", "-print_format", "json", "-show_format", "-show_streams", str(p)],
                       capture_output=True, text=True)
    try:
        j = json.loads(r.stdout or "{}")
    except ValueError:
        return {}
    fmt = j.get("format", {})
    v = next((s for s in j.get("streams", []) if s.get("codec_type") == "video"
              and not s.get("disposition", {}).get("attached_pic")), None)
    a = next((s for s in j.get("streams", []) if s.get("codec_type") == "audio"), None)
    return {"dur": float(fmt.get("duration") or 0), "br": int(fmt.get("bit_rate") or 0),
            "w": (v or {}).get("width"), "h": (v or {}).get("height"), "has_audio": a is not None,
            "acodec": (a or {}).get("codec_name")}


def audio_sig(p: Path, dur: float) -> list[float] | None:
    r = subprocess.run(["ffmpeg", "-v", "error", "-i", str(p), "-t", "20", "-vn", "-ac", "1", "-ar", "4000",
                        "-f", "s16le", "-"], capture_output=True)
    x = np.frombuffer(r.stdout, np.int16).astype(np.float32)
    if x.size < 400:
        return None
    n = x.size // 400
    env = np.sqrt((x[: n * 400].reshape(n, 400) ** 2).mean(axis=1))
    env = np.log1p(env)
    return env.round(3).tolist()


def dhash(im: Image.Image) -> int:
    g = im.convert("L").resize((9, 8), Image.LANCZOS)
    a = np.asarray(g, dtype=np.int16)
    bits = (a[:, 1:] > a[:, :-1]).flatten()
    return int("".join("1" if b else "0" for b in bits), 2)


def video_hashes(p: Path, dur: float) -> list[int]:
    out = []
    for f in (0.2, 0.5, 0.8):
        r = subprocess.run(["ffmpeg", "-v", "error", "-ss", f"{dur * f:.2f}", "-i", str(p), "-frames:v", "1",
                            "-vf", "scale=64:36", "-f", "rawvideo", "-pix_fmt", "rgb24", "-"], capture_output=True)
        if len(r.stdout) >= 64 * 36 * 3:
            out.append(dhash(Image.frombytes("RGB", (64, 36), r.stdout[: 64 * 36 * 3])))
    return out


def analyse(p: Path) -> dict:
    ext = p.suffix.lower()
    rec = {"path": str(p), "ext": ext, "size": p.stat().st_size, "sha1": sha1(p)}
    try:
        if ext in AUDIO or ext in VIDEO:
            rec.update(probe(p))
            if rec.get("has_audio"):
                rec["asig"] = audio_sig(p, rec["dur"])
            if ext in VIDEO and rec.get("w"):
                rec["vh"] = video_hashes(p, rec["dur"])
        elif ext in IMAGE:
            with Image.open(p) as im:
                rec["w"], rec["h"] = im.size
                im.seek(0)
                rec["ih"] = dhash(im.convert("RGBA").convert("RGB"))
    except Exception as e:  # noqa: BLE001
        rec["error"] = str(e)
    return rec


def corr(a: list[float], b: list[float]) -> float:
    n = min(len(a), len(b))
    if n < 8:
        return 0.0
    x, y = np.array(a[:n]), np.array(b[:n])
    if x.std() < 1e-6 or y.std() < 1e-6:
        return 1.0 if abs(x.mean() - y.mean()) < 0.05 else 0.0
    return float(np.corrcoef(x, y)[0, 1])


def ham(a: int, b: int) -> int:
    return bin(a ^ b).count("1")


def quality(r: dict, first_root: str) -> tuple:
    lossless = r["ext"] in (".wav", ".flac", ".png", ".mov")
    res = (r.get("w") or 0) * (r.get("h") or 0)
    rate = r.get("br") or (r["size"] / max(r.get("dur") or 1, 0.1))
    clean = -len(JUNK.findall(Path(r["path"]).name))
    return (r["path"].startswith(first_root), res, lossless, rate, clean, -len(r["path"]))


def main() -> None:
    ap = argparse.ArgumentParser()
    ap.add_argument("roots", nargs="+")
    ap.add_argument("--out", default=str(ROOT / "studio" / "catalog" / "dedupe.json"))
    args = ap.parse_args()
    roots = [ROOT / r for r in args.roots]
    files = [f for r in roots for f in r.rglob("*") if f.is_file() and not f.name.endswith(".sfk")
             and "_Duplicates" not in f.parts]
    print(f"{len(files)} files", flush=True)
    with ThreadPoolExecutor(12) as ex:
        recs = list(ex.map(analyse, files))
    first = str(roots[0])

    parent = list(range(len(recs)))                       # union-find over duplicate links

    def find(i):
        while parent[i] != i:
            parent[i] = parent[parent[i]]
            i = parent[i]
        return i

    def union(i, j, why):
        a, b = find(i), find(j)
        if a != b:
            parent[b] = a
            reasons.append((recs[i]["path"], recs[j]["path"], why))
    reasons: list = []
    by_sha: dict[str, int] = {}
    for i, r in enumerate(recs):
        if r["sha1"] in by_sha:
            union(by_sha[r["sha1"]], i, "identical bytes")
        else:
            by_sha[r["sha1"]] = i
    # near-dup audio (also catches the same meme as .mp3 and .mp4 audio track only when both are audio files)
    aud = sorted([i for i, r in enumerate(recs) if r.get("asig") and r["ext"] in AUDIO], key=lambda i: recs[i]["dur"])
    for k, i in enumerate(aud):
        for j in aud[k + 1:]:
            di, dj = recs[i]["dur"], recs[j]["dur"]
            if dj - di > max(0.15, 0.02 * di):
                break
            if find(i) != find(j) and corr(recs[i]["asig"], recs[j]["asig"]) >= 0.96:
                union(i, j, f"same sound (r={corr(recs[i]['asig'], recs[j]['asig']):.3f})")
    vid = sorted([i for i, r in enumerate(recs) if r.get("vh")], key=lambda i: recs[i]["dur"])
    for k, i in enumerate(vid):
        for j in vid[k + 1:]:
            di, dj = recs[i]["dur"], recs[j]["dur"]
            if dj - di > max(0.2, 0.02 * di):
                break
            a, b = recs[i]["vh"], recs[j]["vh"]
            if find(i) != find(j) and len(a) == len(b) and a and sum(ham(x, y) for x, y in zip(a, b)) / len(a) <= 6:
                union(i, j, "same clip")
    img = [i for i, r in enumerate(recs) if r.get("ih") is not None]
    buckets: dict[int, list[int]] = {}
    for i in img:
        buckets.setdefault(recs[i]["ih"] >> 52, []).append(i)    # coarse bucket on top bits
    for ids in buckets.values():
        for x, i in enumerate(ids):
            for j in ids[x + 1:]:
                ri, rj = recs[i], recs[j]
                ar_i, ar_j = ri["w"] / max(ri["h"], 1), rj["w"] / max(rj["h"], 1)
                if find(i) != find(j) and abs(ar_i - ar_j) < 0.03 and ham(ri["ih"], rj["ih"]) <= 4:
                    union(i, j, "same image")
    groups: dict[int, list[int]] = {}
    for i in range(len(recs)):
        groups.setdefault(find(i), []).append(i)
    dup_groups = []
    for ids in groups.values():
        if len(ids) < 2:
