import numpy as np
from PIL import Image

ROOT = Path(__file__).resolve().parents[2]
AUDIO = {".mp3", ".wav", ".m4a", ".flac", ".ogg", ".aac"}
VIDEO = {".mp4", ".mov", ".webm", ".wmv", ".avi", ".mkv"}
IMAGE = {".png", ".jpg", ".jpeg", ".webp", ".gif"}
JUNK = re.compile(r"\(\s*\d+\s*kbps\s*\)|\(HD\)|\[Mpgun\.com\]|y2mate\.com|yt1s\.com|\(\d+k\)|\(\d\)|copy|copie", re.I)


def sha1(p: Path) -> str:
    h = hashlib.sha1()
    with p.open("rb") as f:
        while b := f.read(1 << 20):
            h.update(b)
    return h.hexdigest()


def probe(p: Path) -> dict:
    r = subprocess.run(["ffprobe", "-v", "error", "-print_format", "json", "-show_format", "-show_streams", str(p)],
                       capture_output=True, text=True)
    try:
        j = json.loads(r.stdout or "{}")
    except ValueError:
        return {}
    fmt = j.get("format", {})
    v = next((s for s in j.get("streams", []) if s.get("codec_type") == "video"
              and not s.get("disposition", {}).get("attached_pic")), None)
    a = next((s for s in j.get("streams", []) if s.get("codec_type") == "audio"), None)
    return {"dur": float(fmt.get("duration") or 0), "br": int(fmt.get("bit_rate") or 0),
            "w": (v or {}).get("width"), "h": (v or {}).get("height"), "has_audio": a is not None,
            "acodec": (a or {}).get("codec_name")}


def audio_sig(p: Path, dur: float) -> list[float] | None:
    r = subprocess.run(["ffmpeg", "-v", "error", "-i", str(p), "-t", "20", "-vn", "-ac", "1", "-ar", "4000",
                        "-f", "s16le", "-"], capture_output=True)
    x = np.frombuffer(r.stdout, np.int16).astype(np.float32)
    if x.size < 400:
        return None
    n = x.size // 400
    env = np.sqrt((x[: n * 400].reshape(n, 400) ** 2).mean(axis=1))
    env = np.log1p(env)
    return env.round(3).tolist()


def dhash(im: Image.Image) -> int:
    g = im.convert("L").resize((9, 8), Image.LANCZOS)
    a = np.asarray(g, dtype=np.int16)
    bits = (a[:, 1:] > a[:, :-1]).flatten()
    return int("".join("1" if b else "0" for b in bits), 2)


def video_hashes(p: Path, dur: float) -> list[int]:
    out = []
    for f in (0.2, 0.5, 0.8):
        r = subprocess.run(["ffmpeg", "-v", "error", "-ss", f"{dur * f:.2f}", "-i", str(p), "-frames:v", "1",
                            "-vf", "scale=64:36", "-f", "rawvideo", "-pix_fmt", "rgb24", "-"], capture_output=True)
