input.content:
"""Second half of organize.py: decide the destination of every asset, then move (logged, reversible).

Destination = <Editing Pack>/<folder>/<clean file name>
  * incoming assets: the tagger's "folder" + "clean_name"
  * existing assets: rules over category / roles / moments / tags / old sub-folder (below)
  * Fonts/ stays exactly where it is (other tools reference those paths)
"""
from __future__ import annotations

import json
import re
from collections import Counter
from pathlib import Path, PurePosixPath

from organize import LOG, PACK, move  # noqa: F401

CAT = Path(__file__).resolve().parent
TAX = json.loads((CAT / "taxonomy.json").read_text(encoding="utf-8"))
FOLDERS = {k for k in TAX["folders"] if not k.startswith("_")}

GAME = re.compile(r"mario|gta|call of duty|\bcod\b|among us|fortnite|roblox|ff7|zelda|pok[eé]mon|street fighter|"
                  r"mortal kombat|halo|metal gear|cs ?go|counter.?strike|sonic|pubg|dbz|dragon ball|kirby|tf2|team fortress|"
                  r"windows (95|98|xp)|ps2|xbox|playstation|nintendo|wii|smash|undertale|crash bandicoot|yoshi", re.I)
GAME_OST = re.compile(r"mario|nintendo|zelda|kirby|undertale|wii|pok[eé]mon|smash|crash|yoshi|animal crossing|3ds|mii|"
                      r"galaxy|odyssey|sunshine|skyward|ocarina|minecraft", re.I)


def has(t: dict, *words) -> bool:
    blob = " ".join([t.get("description") or "", " ".join(t.get("tags") or []), t.get("_title", "")]).lower()
    return any(w in blob for w in words)


def folder_existing(r: dict, t: dict) -> str:
    cat, sub = r["category"], r.get("subfolder", "")
    roles = t.get("roles") or []
    moments = t.get("moments") or []
    title = r.get("title", "")
    t = {**t, "_title": title}
    primary = roles[0] if roles else ""
    if cat == "font":
        return "Fonts"
    if cat == "reference":
        if sub.startswith(("Premiere Pro Presets", "Photoshop Templates")):
            return "Templates & Presets"
        if sub.startswith("Mods, Shaders"):
            return "Mods & Resource Packs"
        return "Reference"
    if cat == "sfx_minecraft":
        return "Sound Effects/Minecraft"
    if cat == "sfx_laugh" or primary == "laugh_track":
        return "Sound Effects/Laughs"
    if cat == "sfx_mlg":
        return "Sound Effects/MLG"
    if cat in ("sfx_ui", "sfx_meme"):
        if primary == "whoosh":
            return "Sound Effects/Whooshes & Swooshes"
        if primary == "riser":
            return "Sound Effects/Risers & Suspense"
        if primary == "ui_sound":
            return "Sound Effects/UI, Clicks & Notifications"
        if primary == "hit":
            return "Sound Effects/Cartoon & Anime" if has(t, "cartoon", "boing", "anime") else \
                "Sound Effects/Hits, Punches & Booms"
        if cat == "sfx_ui":
            return "Sound Effects/UI, Clicks & Notifications"
        if GAME.search(title) and primary not in ("voice_line",):
            return "Sound Effects/Game Sounds"
        if primary == "stinger":
            return "Sound Effects/Stingers & Jingles"
        if primary == "reaction":
            return "Sound Effects/Reactions & Screams"
        if primary == "literal":
            return "Sound Effects/Foley & Real World"
        if has(t, "cartoon", "boing", "anime"):
            return "Sound Effects/Cartoon & Anime"
        return "Sound Effects/Meme Sounds"
    if cat == "music":
        if t.get("copyright_risk") == "high":
            return "Music/Game Soundtracks (copyrighted)" if GAME_OST.search(title) else "Music/Copyrighted (use carefully)"
        if "sad" in moments or has(t, "sad", "emotional", "piano"):
            return "Music/Emotional & Sad"
        if any(m in moments for m in ("suspense", "jumpscare")) or has(t, "scary", "horror", "eerie", "creepy"):
            return "Music/Scary & Suspense"
        if has(t, "phonk", "trap", "edm", "upbeat", "hype", "energetic", "dubstep"):
            return "Music/Hype & Energetic"
        if (t.get("energy") or 3) >= 4 or any(m in moments for m in ("combat", "victory", "chase")) or \
                has(t, "epic", "cinematic", "battle", "action"):
            return "Music/Intense & Cinematic"
        if (t.get("energy") or 3) <= 2 and not has(t, "comedic", "comedy", "funny", "quirky", "sneaky", "silly"):
            return "Music/Chill & Lofi"
        return "Music/Funny & Quirky"
    if cat == "meme_video":
        if "time_skip" in moments or has(t, "time card", "meanwhile", "later"):
            return "Meme Videos/Time Cards & Interludes"
        if "tech_glitch" in moments or has(t, "tv ", "static", "no signal", "vhs", "blue screen"):
            return "Meme Videos/TV & Glitch"
        if (r.get("duration_s") or 99) <= 12 and any(m in moments for m in ("awkward", "shock", "confusion", "punchline")):
            return "Meme Videos/Reactions"
        return "Meme Videos/Clips & Templates"
    if cat == "green_screen":
        if has(t, "wasted", "you died", " ko", "subscribe", "like button", "follow", "stamp", "breaking news",
               "countdown", "to be continued", "triggered", "victory royale", "text"):
            return "Green Screen/Text, Badges & Popups"
        if has(t, "explosion", "hitmarker", "gun", "confetti", "fire", "blood", "shoot", "nuke", "airhorn"):
            return "Green Screen/Effects & Explosions"
        if has(t, "emoji", "logo", "spinning", "star", "icon"):
            return "Green Screen/Emojis & Icons"
        if has(t, "laptop", "hud", "camera", "phone", "tv", "curtain", "frame", "matrix", "math"):
            return "Green Screen/Frames & HUD"
        return "Green Screen/Characters & Memes"
    if cat == "transition":
        return "Transitions/Minecraft" if ("Minecraft" in sub or has(t, "minecraft")) else "Transitions/General"
    if cat == "animation":
        if "Subscribe" in sub or "cta" in moments:
            return "Animations/Subscribe & CTA"
        if "Progress" in sub or "progress" in moments or has(t, "counter", "progress", "hearts"):
            return "Animations/Counters & Progress"
        if "Minecraft" in sub:
            return "Animations/Minecraft UI"
        return "Animations/Extra"
    if cat == "background":
        overlayish = r.get("key_mode") in ("black_screen", "alpha") or (t.get("placement") or "").startswith("overlay")
        if overlayish:
            if has(t, "snow", "rain", "fog", "lightning"):
                return "Overlays & VFX/Weather"
            if has(t, "vhs", "camcorder", "glitch", "scanline", "film"):
                return "Overlays & VFX/Glitch & VHS"
            if has(t, "speed line", "ray"):
                return "Overlays & VFX/Speed Lines & Shapes"
            return "Overlays & VFX/Particles & Sparkles"
        if "Moving Blocks" in sub or has(t, "minecraft"):
            return "Backgrounds/Minecraft"
        if "Skies" in sub or has(t, "sky", "space", "star", "nebula", "cloud"):
            return "Backgrounds/Skies & Space"
        if r.get("kind") == "video":
            return "Backgrounds/Motion Loops"
        return "Backgrounds/Textures & Patterns"
    if cat == "image":
        m = {"Expressions & Faces": "Images/Faces & Expressions", "Phonk Edit Faces": "Images/Meme Faces & Characters",
             "Minecraft Item GIFs": "Images/Minecraft Items", "Minecraft Structures": "Images/Minecraft Scenes & Structures",
             "Minecraft GUIs & more": "Images/Minecraft GUIs & Titles",
             "Minecraft Titles & Mojang Studios": "Images/Minecraft GUIs & Titles", "Logos": "Images/Logos & Brands",
             "Particles & PVP Particles": "Images/Particles & Effects", "Borders & Frames": "Images/Borders & Frames",
             "Screen Borders": "Images/Borders & Frames", "Thumbnail Lines": "Images/Arrows, Shapes & Lines"}
        for k, v in m.items():
            if sub.endswith(k):
                return v
        if has(t, "emoji", "sticker", "troll", "skull", "fire emoji"):
            return "Images/Emojis & Stickers"
        if has(t, "creeper", "zombie", "skeleton", "enderman", "steve", "alex", "mob", "villager", "pig", "cow"):
            return "Images/Minecraft Mobs & Characters"
        if has(t, "minecraft") and has(t, "item", "sword", "pickaxe", "block", "diamond", "apple"):
            return "Images/Minecraft Items"
        if has(t, "arrow", "circle", "line", "shape"):
            return "Images/Arrows, Shapes & Lines"
        if has(t, "face", "meme", "character", "person"):
            return "Images/Meme Faces & Characters"
        return "Images/Thumbnail Assets"
    return "Reference"


FOLDER_CATEGORY = [
    ("Sound Effects/Minecraft", "sfx_minecraft"), ("Sound Effects/Laughs", "sfx_laugh"), ("Sound Effects/MLG", "sfx_mlg"),
    ("Sound Effects/Whooshes & Swooshes", "sfx_ui"), ("Sound Effects/Hits, Punches & Booms", "sfx_ui"),
    ("Sound Effects/Risers & Suspense", "sfx_ui"), ("Sound Effects/UI, Clicks & Notifications", "sfx_ui"),
    ("Sound Effects", "sfx_meme"), ("Music", "music"), ("Meme Videos", "meme_video"), ("Green Screen", "green_screen"),
    ("Overlays & VFX", "overlay"), ("Transitions", "transition"), ("Animations", "animation"),
    ("Backgrounds", "background"), ("Images", "image"), ("Fonts", "font"),
]

JUNK = re.compile(r"\(\s*\d+\s*kbps\s*\)|\(HD\)|\[Mpgun\.com\]|y2mate\.com\s*-\s*|yt1s\.com\s*-\s*|\(\d+k\)|"
                  r"\(online-audio-converter\.com\)|_?\(getmp3[^)]*\)|\s-\s*(Gaming |MLG |Comical )?Sound Effects?(\s*\(HD\))?|"
                  r"\[Download_Link\][^.]*|_kkD\w+", re.I)


def clean_filename(name: str, ext: str) -> str:
    n = JUNK.sub("", name)
    n = re.sub(r'[<>:"/\\|?*]', "", n).replace("_", " ")
    n = re.sub(r"\s{2,}", " ", n).strip(" -.")
    return (n or "asset")[:90] + ext


def load_tags() -> dict[str, dict]:
    tags: dict[str, dict] = {}
    for f in sorted((CAT / "tags").glob("*.json")):
        for t in json.loads(f.read_text(encoding="utf-8")):
            tags[t["id"]] = t
    return tags


def plan() -> None:
    scan = json.loads((CAT / "scan.json").read_text(encoding="utf-8"))
    tags = load_tags()
    out, missing, bad = [], [], []
    for r in scan:
        if r.get("root", "Editing Pack") != "Editing Pack" or r.get("duplicate_of"):
            continue
        rel = r["path"]
        if rel.startswith(("_Duplicates", "Fonts/")):
            continue
        t = tags.get(r["id"], {})
        if rel.startswith("_Incoming/"):
            folder = t.get("folder")
            if not folder:
                missing.append(rel)
                continue
            name = clean_filename(t["clean_name"], r["ext"]) if t.get("clean_name") else \
                clean_filename(PurePosixPath(rel).stem, r["ext"])
        else:
            folder = folder_existing(r, t)
            name = clean_filename(PurePosixPath(rel).stem, r["ext"])
        if folder not in FOLDERS:
            bad.append((rel, folder))
            folder = "Reference" if folder is None else folder
        out.append({"id": r["id"], "from": rel, "to": f"{folder}/{name}"})
    # collisions -> " (2)"
    seen: Counter = Counter()
    for o in out:
        key = o["to"].lower()
        seen[key] += 1
