    n = re.sub(r'[<>:"/\\|?*]', "", n).replace("_", " ")
    n = re.sub(r"\s{2,}", " ", n).strip(" -.")
    return (n or "asset")[:90] + ext


def load_tags() -> dict[str, dict]:
    tags: dict[str, dict] = {}
    for f in sorted((CAT / "tags").glob("*.json")):
        for t in json.loads(f.read_text(encoding="utf-8")):
            tags[t["id"]] = t
    return tags


def plan() -> None:
    scan = json.loads((CAT / "scan.json").read_text(encoding="utf-8"))
    tags = load_tags()
    out, missing, bad = [], [], []
    for r in scan:
        if r.get("root", "Editing Pack") != "Editing Pack" or r.get("duplicate_of"):
            continue
        rel = r["path"]
        if rel.startswith(("_Duplicates", "Fonts/")):
            continue
        t = tags.get(r["id"], {})
        if rel.startswith("_Incoming/"):
            folder = t.get("folder")
            if not folder:
                missing.append(rel)
                continue
            name = clean_filename(t["clean_name"], r["ext"]) if t.get("clean_name") else \
                clean_filename(PurePosixPath(rel).stem, r["ext"])
        else:
            folder = folder_existing(r, t)
            name = clean_filename(PurePosixPath(rel).stem, r["ext"])
        if folder not in FOLDERS:
            bad.append((rel, folder))
            folder = "Reference" if folder is None else folder
        out.append({"id": r["id"], "from": rel, "to": f"{folder}/{name}"})
    # collisions -> " (2)"
    seen: Counter = Counter()
    for o in out:
        key = o["to"].lower()
        seen[key] += 1
        if seen[key] > 1:
            p = PurePosixPath(o["to"])
            o["to"] = str(p.with_name(f"{p.stem} ({seen[key]}){p.suffix}"))
    (CAT / "organize_plan.json").write_text(json.dumps({"moves": out, "untagged_incoming": missing,
                                                         "bad_folders": bad}, indent=1, ensure_ascii=False),
                                           encoding="utf-8")
    c = Counter(o["to"].rsplit("/", 1)[0] for o in out)
    print(f"{len(out)} assets planned, {len(missing)} incoming without a folder, {len(bad)} bad folders")
    for k, v in sorted(c.items()):
        print(f"  {v:5d}  {k}")


def apply() -> None:
    p = json.loads((CAT / "organize_plan.json").read_text(encoding="utf-8"))
    n = 0
    for o in p["moves"]:
        src, dst = PACK / o["from"], PACK / o["to"]
        if src.exists() and src != dst:
            move(src, dst, "reorganise")
            n += 1
    # prune now-empty old folders
    for d in sorted((x for x in PACK.rglob("*") if x.is_dir()), key=lambda x: -len(x.parts)):
        try:
            if not any(d.iterdir()):
                d.rmdir()
        except OSError:
            pass
    print(f"moved {n} files")

