def _coerce(spec: dict, value):
    t = spec.get("type", "string")
    if t == "number":
        f = float(value)
        return int(f) if f.is_integer() else f
    if t == "boolean":
        if isinstance(value, bool):
            return value
        return str(value).strip().lower() in ("1", "true", "yes", "on")
    return str(value)


def resolve_vars(name: str, vars: dict | None = None) -> dict:
    """Manifest defaults (brand refs resolved from brand.json) overlaid with caller vars, type-coerced."""
    m = _manifest(name)
    brand = load_brand()
    specs = m.get("vars", {})
    out = {}
    for key, spec in specs.items():
        out[key] = _brand_lookup(brand, spec["brand"]) if "brand" in spec else spec.get("default")
    for key, val in (vars or {}).items():
        if key not in specs:
            raise ValueError(f"template '{name}' has no var '{key}' (vars: {', '.join(specs)})")
        out[key] = val
    return {k: _coerce(specs[k], v) for k, v in out.items()}


def _fingerprint(tdir: Path) -> list:
    files = [tdir / f for f in SOURCE_FILES if (tdir / f).exists()]
    files += [p for p in sorted(SHARED.glob("*")) if p.is_file()]
    files += [FONTS / f for _, f in FONT_FACES] + [BRAND_JSON]

