def load_favorites(existing: set[str]) -> set[str]:
    """favorites.json ids, resolved through redirects.json (chains followed) to the last id along the chain
    that exists in this build (some redirect targets are stale)."""
    try:
        ids = json.loads((OUT / "favorites.json").read_text(encoding="utf-8")).get("ids") or []
    except (OSError, ValueError, AttributeError):
        return set()
    try:
        redirects = json.loads((OUT / "redirects.json").read_text(encoding="utf-8"))
    except (OSError, ValueError):
        redirects = {}
    out = set()
    for i in ids:
        chain = [i]
        while chain[-1] in redirects and redirects[chain[-1]] not in chain:
            chain.append(redirects[chain[-1]])
        out.add(next((c for c in reversed(chain) if c in existing), chain[-1]))

