js=r'''
// ---------------------------------------------------------------- brand library
const BL = store.get("brandlib", { set: "emotes", q: "", favs: false });
const SETS = { emotes: "Emotes", characters: "Characters", logos: "Logos & icons", cta: "CTA banners",
  overlays: "Stream overlays", avatar: "Narrator avatar", art: "Channel art" };
async function BrandLibrary() {
  const d = await api("/api/brand/library");
  const counts = Object.fromEntries(Object.keys(SETS).map((k) => [k, d.stickers.filter((s) => s.set === k).length]));
  counts.avatar = Object.keys(d.avatar_moods).length; counts.art = d.art.length;
  const logo = d.logo?.main ? `<img class="bl-logo" src="/media/studio/${enc(d.logo.main)}" alt="">` : `<h1>${esc(d.channel_name || "")}</h1>`;
  view.innerHTML = `
    <div class="bl-head card">${logo}
      <div style="flex:1;min-width:220px"><h1 style="margin:0">Brand library</h1>
        <p class="sub" style="margin:4px 0 8px">Everything that makes the channel look like <b>${esc(d.channel_name || "")}</b>: mascot emotes, poses, logos and banners, cut out with transparency and tagged so the auto-editor can use them.</p>
        <div class="row">${Object.entries(d.colors).map(([k, c]) => `<button class="bl-swatch" data-hex="${c}" title="${k} ${c} (click to copy)" style="background:${c}"></button>`).join("")}</div></div></div>
    <div class="row" style="margin:14px 0 8px;flex-wrap:wrap">
      <div class="chips" id="blsets">${Object.entries(SETS).map(([k, v]) => `<span class="chip ${BL.set === k ? "on" : ""}" data-s="${k}">${v} <span class="faint">${counts[k]}</span></span>`).join("")}</div>
      <span class="spacer"></span>
      <input id="blq" type="search" placeholder="Search: cry, gg, diamond, death…" value="${esc(BL.q)}" style="min-width:220px">
      <label class="chip fav-chip ${BL.favs ? "on" : ""}" id="blfav">★ Favourites</label>
    </div>
    <div id="blbody"></div>`;
  $$(".bl-swatch").forEach((b) => b.onclick = () => navigator.clipboard.writeText(b.dataset.hex).then(() => toast("Copied " + b.dataset.hex)));
  $$("#blsets .chip").forEach((c) => c.onclick = () => { BL.set = c.dataset.s; store.set("brandlib", BL); BrandLibrary(); });
  $("#blq").oninput = (e) => { BL.q = e.target.value; store.set("brandlib", BL); body(); };
  $("#blfav").onclick = () => { BL.favs = !BL.favs; store.set("brandlib", BL); BrandLibrary(); };

  function body() {
    const el = $("#blbody");
    if (BL.set === "avatar") {
      el.innerHTML = `<div class="card"><p class="muted" style="margin-top:0">The narrator avatar uses one emote per mood. Pick a different face for any mood from the <b>Emotes</b> tab (the 🙂 menu on a card).</p>
        <div class="row" style="gap:16px;flex-wrap:wrap">${Object.entries(d.avatar_moods).map(([m, f]) => `<div style="text-align:center"><div class="bl-tile" style="width:150px;height:150px"><img src="/media/studio/${enc(f)}"></div><b>${m}</b></div>`).join("")}</div>
        ${d.avatar_preview ? `<h3>All states (talk / blink)</h3><img src="/media/studio/${d.avatar_preview}?v=${Date.now()}" style="width:100%;border-radius:8px">` : ""}</div>`;
      return;
    }
    if (BL.set === "art") {
      el.innerHTML = `<p class="muted">Your original files in <code>Minecraft Channel/Crodie/</code>.</p><div class="grid bl-art">${[...d.art, ...d.sheets].map((f) => `<div class="card"><img src="/media/brandsrc/${enc(f)}" style="width:100%;border-radius:6px" loading="lazy"><div class="row"><b>${esc(f)}</b><span class="spacer"></span><a class="btn sm" href="/media/brandsrc/${enc(f)}" download>⤓</a></div></div>`).join("")}</div>`;
      return;
    }
    const q = BL.q.trim().toLowerCase();
    const items = d.stickers.filter((s) => s.set === BL.set && (!BL.favs || s.favorite)
      && (!q || (s.id + " " + s.moments.join(" ") + " " + s.mood).toLowerCase().includes(q)));
    el.innerHTML = items.length ? `<div class="grid bl-grid">${items.map((s) => `
      <div class="card bl-card" data-id="${s.id}">
