          ${s.set === "logos" ? `<select class="bl-logo-set sm" title="Use as a channel logo"><option value="">use as…</option><option value="watermark">watermark</option><option value="main">main logo</option><option value="icon">icon</option><option value="badge">badge</option></select>` : ""}
        </div>
        <div class="bl-anim"></div></div>`).join("")}</div>` : `<div class="empty">Nothing here${q ? ` for "${esc(q)}"` : ""}.</div>`;
    const byId = (n) => d.stickers.find((s) => s.id === n.closest(".bl-card").dataset.id);
