from pathlib import Path

UI = Path(r"C:\Users\edmem\OneDrive\Desktop\Minecraft Channel\studio\ui")
JS = Path(__file__).with_name("brandlib.js").read_text(encoding="utf-8")

p = UI / "index.html"
s = p.read_text(encoding="utf-8")
if "#/brandlib" not in s:
    a = '    <a href="#/brand" data-nav="brand">'
    assert s.count(a) == 1
    s = s.replace(a, '    <a href="#/brandlib" data-nav="brandlib"><span class="ico">◆</span>Brand library</a>\n' + a)
    p.write_text(s, encoding="utf-8")

p = UI / "app.js"
s = p.read_text(encoding="utf-8")
if "async function BrandLibrary" not in s:
    s = s.replace("jobs: Jobs, brand: Brand,", "jobs: Jobs, brand: Brand, brandlib: BrandLibrary,")
    anchor = "// ---------------------------------------------------------------- jobs"
    assert s.count(anchor) == 1
    s = s.replace(anchor, JS + anchor)
    p.write_text(s, encoding="utf-8")

p = UI / "style.css"
s = p.read_text(encoding="utf-8")
if ".bl-tile" not in s:
    s += """
/* brand library */
.bl-head { display: flex; gap: 18px; align-items: center; flex-wrap: wrap; }
.bl-logo { height: 92px; max-width: 260px; object-fit: contain; }
.bl-swatch { width: 34px; height: 34px; border-radius: 8px; border: 1px solid var(--line); cursor: pointer; padding: 0; }
.bl-grid { grid-template-columns: repeat(auto-fill, minmax(190px, 1fr)); }
.bl-tile { aspect-ratio: 1; border-radius: 6px; display: grid; place-items: center; overflow: hidden;
  background: repeating-conic-gradient(#2a2d31 0% 25%, #222528 0% 50%) 50% / 18px 18px; }
.bl-tile img { max-width: 92%; max-height: 92%; object-fit: contain; }
.bl-name { font-size: 13px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; text-transform: capitalize; }
.bl-star.on { color: var(--gold); border-color: var(--gold); }
.chip.sm, .btn.sm, select.sm { font-size: 11px; padding: 2px 7px; }
"""
    p.write_text(s, encoding="utf-8")
print("ok")

